// Tightly coupled class
class Engine {
    void start() {
        System.out.println("Engine started");
    }
}

class Car {
    private Engine engine;   // Car is dependent on Engine

    Car() {
        engine = new Engine();   // Strong coupling
    }

    void drive() {
        engine.start();
        System.out.println("Car is moving");
    }
}

public class Main {
    public static void main(String[] args) {
        Car myCar = new Car();
        myCar.drive();
    }
}

// Highly cohesive class
class Calculator {

    int add(int a, int b) {
        return a + b;
    }

    int subtract(int a, int b) {
        return a - b;
    }
}

public class Main {
    public static void main(String[] args) {
        Calculator calc = new Calculator();

        System.out.println("Addition: " + calc.add(10, 5));
        System.out.println("Subtraction: " + calc.subtract(10, 5));
    }
}

// Associated class
class PrimeMinister {
    String name;

    PrimeMinister(String name) {
        this.name = name;
    }
}

// Another associated class
class Country {
    String countryName;
    PrimeMinister pm;   // Association

    Country(String countryName, PrimeMinister pm) {
        this.countryName = countryName;
        this.pm = pm;
    }

    void showDetails() {
        System.out.println("Country: " + countryName);
        System.out.println("Prime Minister: " + pm.name);
    }
}

public class Main {
    public static void main(String[] args) {
        PrimeMinister pm = new PrimeMinister("John");
        Country country = new Country("ABC Nation", pm);

        country.showDetails();
    }
}

// Aggregated class
class Department {
    String deptName;

    Department(String deptName) {
        this.deptName = deptName;
    }
}

// Aggregator class
class University {
    String universityName;
    Department department;   // Aggregation (HAS-A relationship)

    University(String universityName, Department department) {
        this.universityName = universityName;
        this.department = department;
    }

    void showDetails() {
        System.out.println("University: " + universityName);
        System.out.println("Department: " + department.deptName);
    }
}

public class Main {
    public static void main(String[] args) {
        Department dept = new Department("Computer Science");
        University uni = new University("ABC University", dept);

        uni.showDetails();
    }
}

// Composed class
class Engine {
    void start() {
        System.out.println("Engine started");
    }
}

// Owner class
class Car {
    private Engine engine;   // Composition (strong HAS-A relationship)

    Car() {
        engine = new Engine();   // Engine created inside Car
    }

    void drive() {
        engine.start();
        System.out.println("Car is moving");
    }
}

public class Main {
    public static void main(String[] args) {
        Car myCar = new Car();
        myCar.drive();
    }
}
